mapper.select:
SELECT rf.FORECAST_ID AS forecastId, rf.FORECAST_NO AS forecastNo, rf.FORECAST_NAME AS forecastName, rf.MODEL_ID AS modelId, bm.MODEL_NAME AS modelName, rf.FORECAST_TYPE AS forecastType, rf.START_PERIOD AS startPeriod, rf.END_PERIOD AS endPeriod, rf.VERSION AS version, rf.BASE_TYPE AS baseType, rf.FORECAST_DESC AS forecastDesc, rf.STATUS AS status, rf.SUBMIT_USER AS submitUser, rf.SUBMIT_TIME AS submitTime, rf.APPROVE_USER AS approveUser, rf.APPROVE_TIME AS approveTime, rf.APPROVE_OPINION AS approveOpinion, rf.ORG_ID AS orgId, rf.CREATE_USER AS createUser, rf.CREATE_TIME AS createTime, rf.UPDATE_USER AS updateUser, rf.UPDATE_TIME AS updateTime FROM TBL_ROLLING_FORECAST rf LEFT JOIN TBL_BUDGET_MODEL bm ON rf.MODEL_ID = bm.MODEL_ID
AND rf.FORECAST_NO LIKE '%' || #{forecastNo} || '%'
AND rf.FORECAST_NAME LIKE '%' || #{forecastName} || '%'
AND rf.MODEL_ID = #{modelId}
AND rf.FORECAST_TYPE = #{forecastType}
AND rf.START_PERIOD >= #{startPeriod}
AND rf.END_PERIOD <= #{endPeriod}
AND rf.VERSION = #{version}
AND rf.STATUS = #{status}
AND rf.CREATE_TIME >= TO_TIMESTAMP(#{startTime}, 'YYYY-MM-DD HH24:MI:SS')
AND rf.CREATE_TIME <= TO_TIMESTAMP(#{endTime}, 'YYYY-MM-DD HH24:MI:SS')
AND rf.ORG_ID = #{orgId}
ORDER BY rf.CREATE_TIME DESC
